{
  "1": {
    "class_type": "CheckpointLoaderSimple",
    "inputs": {
      "ckpt_name": "animagineXL_anime_v3.safetensors"
    }
  },
  "2": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "clip": ["1", 1],
      "text": "traditional 1990s cel animation key visual, a sneaker caught mid-air above a city rooftop, laces lifting in the wind, soft skyline in the background, clean ink outlines, flat cel shading with one shadow tone and one highlight tone, deep navy with a single coral accent, bright high-key studio light on a pale backdrop, quiet and luxurious mood, calm negative space around the subject, clearly readable at thumbnail size, no watermark, no logo, no border, no frame"
    }
  },
  "3": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "clip": ["1", 1],
      "text": "3D render, photorealistic, blurry, watermark, logo, border, frame, extra objects, cluttered, low contrast, muddy colors, gradient shading, soft focus"
    }
  },
  "4": {
    "class_type": "EmptyLatentImage",
    "inputs": {
      "width": 1080,
      "height": 1080,
      "batch_size": 1
    }
  },
  "5": {
    "class_type": "KSampler",
    "inputs": {
      "model": ["1", 0],
      "seed": 42,
      "steps": 30,
      "cfg": 7.5,
      "sampler_name": "dpmpp_2m",
      "scheduler": "karras",
      "positive": ["2", 0],
      "negative": ["3", 0],
      "latent_image": ["4", 0],
      "denoise": 1.0
    }
  },
  "6": {
    "class_type": "VAEDecode",
    "inputs": {
      "samples": ["5", 0],
      "vae": ["1", 2]
    }
  },
  "7": {
    "class_type": "ImageScale",
    "inputs": {
      "image": ["6", 0],
      "upscale_method": "lanczos",
      "width": 1080,
      "height": 1080,
      "crop": "disabled"
    }
  },
  "8": {
    "class_type": "SaveImage",
    "inputs": {
      "images": ["7", 0],
      "filename_prefix": "northwind_coffee_key_visual"
    }
  }
}

